/// Chrome soft-wrap opportunity between two printable ASCII characters (`prev2` = the one before `prev`, 0 = none).
inline bool chb_ascii_break(char16_t prev2, char16_t prev, char16_t next) {
    if (prev == u'-' && next >= u'0' && next <= u'9')
        return (prev2 >= u'0' && prev2 <= u'9') || (prev2 >= u'a' && prev2 <= u'z') || (prev2 >= u'A' && prev2 <= u'Z');
    const int b = int(next) - 0x21;
    return (kChbAsciiBreak[int(prev) - 0x21][b / 8] >> (b % 8)) & 1;
}
inline bool chb_is_ascii_graphic(char16_t c) { return c >= 0x21 && c <= 0x7E; }

